function build(grade:Grade,pack:Pack):GeneratedCompleteSet{const tag=`generated-${grade}-set-${pack.id}`;const listening:QuestionSet={id:`${tag}-listening`,title:`${pack.label} · Listening`,section:"listening",instruction:"Listen twice and answer questions 1–10.",script:pack.listening.script,audioMode:"speech",items:pack.listening.questions.map((row,index)=>q(grade,pack.id,"listening",index,row))};const reading:QuestionSet={id:`${tag}-reading`,title:`${pack.label} · Reading`,section:"reading",instruction:"Read the text and answer questions 1–10.",items:pack.reading.questions.map((row,index)=>q(grade,pack.id,"reading",index,row,pack.reading.passage))};const useOfEnglish:QuestionSet={id:`${tag}-use-of-english`,title:`${pack.label} · Use of English`,section:"use-of-english",instruction:"Choose the best word or form.",items:pack.uoe.map((row,index)=>q(grade,pack.id,"use-of-english",index,row))};const w=pack.writing,writing:QuestionSet={id:`${tag}-writing`,title:`${pack.label} · Writing`,section:"writing",instruction:"Complete the writing task.",items:[{id:`${tag}-writing-01`,grade,year:2026,stage:"training",source:"original-olympic-english-lab",sourceLabel:"OLYMPIC ENGLISH LAB · авторский комплект 2026",platformLabel:"OLYMPIC ENGLISH LAB",section:"writing",skill:"Writing",subskill:"competition writing",difficulty:"advanced",type:"writing",instruction:"Complete the writing task.",text:w.text,options:[],acceptedAnswers:[],points:20,explanation:"Teacher review.",tags:["original","generated-olympiad","2026",`generated-set:${pack.id}`],needsReview:true,wordLimit:{min:w.min,max:w.max},requirements:w.requirements,...(w.opening?{requiredOpening:w.opening}:{})}]};return{id:pack.id,label:pack.label,listening,reading,useOfEnglish,writing}}

